INSERT INTO public.recipes (id, title, category, cuisine, description, cook_time, servings, difficulty, dietary_tags, ingredients, instructions, nutrition, image_key) VALUES
('1','Mediterranean Pasta Bowl','Meals','Italian','A fresh and flavorful pasta dish with cherry tomatoes, basil, and garlic.','25 min',4,'Easy',ARRAY['Vegetarian']::text[],ARRAY['400g pasta of choice','2 cups cherry tomatoes, halved','4 cloves garlic, minced','1/4 cup fresh basil, chopped','3 tbsp olive oil','1/2 cup parmesan cheese, grated','Salt and pepper to taste','Red pepper flakes (optional)']::text[],ARRAY['Bring a large pot of salted water to boil and cook pasta according to package directions.','While pasta cooks, heat olive oil in a large pan over medium heat.','Add garlic and sauté for 1 minute until fragrant.','Add cherry tomatoes and cook for 5-7 minutes until they start to burst.','Drain pasta, reserving 1 cup of pasta water.','Add pasta to the pan with tomatoes, tossing to combine.','Add pasta water as needed to create a light sauce.','Stir in fresh basil and parmesan cheese.','Season with salt, pepper, and red pepper flakes if desired.','Serve immediately with extra parmesan on top.']::text[],'{"calories": 450, "protein": "15g", "carbs": "65g", "fat": "14g", "fiber": "4g"}'::jsonb,'1'),
('7','Beef Tacos','Meals','Mexican','Classic Mexican street tacos with seasoned beef and fresh toppings.','30 min',6,'Easy',ARRAY['Gluten-Free']::text[],ARRAY['1 lb ground beef','Taco seasoning','12 corn tortillas','Lettuce, tomatoes, cheese','Sour cream','Salsa','Lime wedges']::text[],ARRAY['Brown ground beef in a large skillet over medium-high heat.','Drain excess fat and add taco seasoning with 1/4 cup water.','Simmer for 5 minutes until sauce thickens.','Warm tortillas in a dry skillet or microwave.','Fill tortillas with beef and desired toppings.','Serve with lime wedges and extra salsa.']::text[],'{"calories": 380, "protein": "22g", "carbs": "32g", "fat": "18g", "fiber": "4g"}'::jsonb,'7'),
('8','Chicken Stir Fry','Meals','Asian','Quick and healthy Asian-inspired chicken with colorful vegetables.','20 min',4,'Easy',ARRAY['Gluten-Free']::text[],ARRAY['500g chicken breast, sliced','Mixed vegetables (broccoli, peppers, carrots)','Soy sauce','Ginger, garlic','Sesame oil','Rice for serving']::text[],ARRAY['Heat sesame oil in a wok or large pan over high heat.','Add chicken and stir-fry for 5-6 minutes until cooked.','Remove chicken and set aside.','Add vegetables and stir-fry for 4 minutes.','Return chicken to pan with soy sauce and seasonings.','Toss everything together and serve over rice.']::text[],'{"calories": 320, "protein": "35g", "carbs": "25g", "fat": "8g", "fiber": "5g"}'::jsonb,'8'),
('9','Margherita Pizza','Meals','Italian','Classic Italian pizza with fresh mozzarella, tomatoes, and basil.','45 min',4,'Medium',ARRAY['Vegetarian']::text[],ARRAY['Pizza dough','San Marzano tomatoes','Fresh mozzarella','Fresh basil','Olive oil','Salt']::text[],ARRAY['Preheat oven to 475°F with pizza stone if available.','Roll out pizza dough to desired thickness.','Spread crushed tomatoes over dough.','Add torn mozzarella pieces.','Drizzle with olive oil and season with salt.','Bake for 12-15 minutes until crust is golden.','Top with fresh basil leaves before serving.']::text[],'{"calories": 420, "protein": "18g", "carbs": "55g", "fat": "14g", "fiber": "3g"}'::jsonb,'9'),
('10','Salmon Teriyaki','Meals','Japanese','Glazed salmon with sweet and savory teriyaki sauce.','25 min',4,'Easy',ARRAY['Gluten-Free']::text[],ARRAY['4 salmon fillets','Teriyaki sauce','Honey','Garlic','Sesame seeds','Green onions']::text[],ARRAY['Mix teriyaki sauce with honey and minced garlic.','Marinate salmon for 15 minutes.','Heat oven to 400°F.','Place salmon on baking sheet and brush with marinade.','Bake for 12-15 minutes until flaky.','Garnish with sesame seeds and green onions.']::text[],'{"calories": 380, "protein": "42g", "carbs": "18g", "fat": "15g", "fiber": "0g"}'::jsonb,'10'),
('11','Lamb Curry','Meals','Indian','Rich Indian curry with tender lamb in aromatic spices.','90 min',6,'Hard',ARRAY['Gluten-Free']::text[],ARRAY['1kg lamb shoulder, cubed','Curry powder','Coconut milk','Tomatoes','Onions, ginger, garlic','Cilantro']::text[],ARRAY['Brown lamb pieces in a large pot.','Remove lamb and sauté onions, ginger, and garlic.','Add curry powder and toast for 1 minute.','Return lamb with tomatoes and coconut milk.','Simmer for 75 minutes until lamb is tender.','Garnish with cilantro and serve with rice or naan.']::text[],'{"calories": 520, "protein": "38g", "carbs": "15g", "fat": "35g", "fiber": "3g"}'::jsonb,'11'),
('12','Pad Thai','Meals','Thai','Authentic Thai stir-fried noodles with shrimp and peanuts.','30 min',4,'Medium',ARRAY['Gluten-Free']::text[],ARRAY['Rice noodles','Shrimp','Eggs','Bean sprouts','Peanuts','Tamarind paste','Fish sauce','Lime']::text[],ARRAY['Soak rice noodles in warm water for 30 minutes.','Make sauce with tamarind paste, fish sauce, and sugar.','Stir-fry shrimp in hot wok, then remove.','Scramble eggs, add drained noodles and sauce.','Add shrimp and bean sprouts, toss well.','Serve with crushed peanuts and lime wedges.']::text[],'{"calories": 460, "protein": "28g", "carbs": "58g", "fat": "12g", "fiber": "3g"}'::jsonb,'12'),
('13','Lasagna','Meals','Italian','Classic Italian layered pasta with rich meat sauce and cheese.','90 min',8,'Medium',ARRAY[]::text[],ARRAY['Lasagna noodles','Ground beef','Ricotta cheese','Mozzarella','Parmesan','Marinara sauce','Italian herbs']::text[],ARRAY['Brown beef with onions and garlic, add marinara.','Cook lasagna noodles according to package.','Mix ricotta with egg and herbs.','Layer sauce, noodles, ricotta, and mozzarella in baking dish.','Repeat layers, ending with mozzarella and parmesan.','Bake at 375°F for 45 minutes.','Let rest 15 minutes before serving.']::text[],'{"calories": 580, "protein": "32g", "carbs": "48g", "fat": "28g", "fiber": "4g"}'::jsonb,'13'),
('14','BBQ Ribs','Meals','American','Slow-cooked pork ribs with smoky BBQ glaze.','180 min',4,'Hard',ARRAY['Gluten-Free']::text[],ARRAY['2 racks pork ribs','BBQ rub','BBQ sauce','Apple cider vinegar','Brown sugar']::text[],ARRAY['Remove membrane from ribs and apply dry rub.','Wrap ribs in foil and refrigerate for 2 hours.','Preheat oven to 275°F.','Bake wrapped ribs for 2.5 hours.','Unwrap, brush with BBQ sauce.','Broil for 5 minutes until caramelized.','Let rest 10 minutes before cutting.']::text[],'{"calories": 680, "protein": "45g", "carbs": "28g", "fat": "42g", "fiber": "1g"}'::jsonb,'14'),
('15','Sushi Rolls','Meals','Japanese','Homemade sushi with fresh fish and vegetables.','60 min',4,'Hard',ARRAY['Gluten-Free']::text[],ARRAY['Sushi rice','Nori sheets','Fresh salmon or tuna','Cucumber','Avocado','Rice vinegar','Soy sauce','Wasabi']::text[],ARRAY['Cook sushi rice and season with rice vinegar.','Let rice cool to room temperature.','Place nori on bamboo mat, spread rice evenly.','Add fish and vegetables in a line.','Roll tightly using the mat.','Slice with sharp wet knife.','Serve with soy sauce, wasabi, and pickled ginger.']::text[],'{"calories": 380, "protein": "18g", "carbs": "62g", "fat": "8g", "fiber": "3g"}'::jsonb,'15'),
('2','Fresh Garden Salad','Salads','American','Crisp mixed greens with colorful vegetables and a tangy vinaigrette.','10 min',2,'Easy',ARRAY['Vegetarian','Vegan','Gluten-Free']::text[],ARRAY['4 cups mixed salad greens','1 cucumber, sliced','1 cup cherry tomatoes, halved','1 red bell pepper, sliced','1/4 red onion, thinly sliced','1/2 cup shredded carrots','3 tbsp olive oil','2 tbsp balsamic vinegar','1 tsp honey','Salt and pepper to taste']::text[],ARRAY['Wash and dry all vegetables thoroughly.','In a large bowl, combine mixed greens, cucumber, tomatoes, bell pepper, onion, and carrots.','In a small bowl, whisk together olive oil, balsamic vinegar, honey, salt, and pepper.','Pour dressing over salad just before serving.','Toss gently to coat all ingredients.','Serve immediately for best crispness.']::text[],'{"calories": 180, "protein": "3g", "carbs": "15g", "fat": "12g", "fiber": "5g"}'::jsonb,'2'),
('16','Caesar Salad','Salads','American','Classic Caesar with crispy romaine, croutons, and creamy dressing.','15 min',4,'Easy',ARRAY['Vegetarian']::text[],ARRAY['Romaine lettuce','Parmesan cheese','Croutons','Caesar dressing','Lemon','Black pepper']::text[],ARRAY['Tear romaine into bite-sized pieces.','Toss lettuce with Caesar dressing.','Add croutons and shaved parmesan.','Squeeze fresh lemon juice over top.','Grind black pepper generously.','Serve immediately while croutons are crispy.']::text[],'{"calories": 220, "protein": "8g", "carbs": "12g", "fat": "16g", "fiber": "3g"}'::jsonb,'16'),
('17','Greek Salad','Salads','Greek','Mediterranean salad with feta, olives, and fresh vegetables.','12 min',4,'Easy',ARRAY['Vegetarian','Gluten-Free']::text[],ARRAY['Cucumbers','Tomatoes','Red onion','Feta cheese','Kalamata olives','Olive oil','Oregano','Lemon juice']::text[],ARRAY['Chop cucumbers, tomatoes, and onion into chunks.','Combine vegetables in a large bowl.','Add olives and crumbled feta.','Drizzle with olive oil and lemon juice.','Sprinkle with oregano.','Toss gently and serve chilled.']::text[],'{"calories": 190, "protein": "6g", "carbs": "10g", "fat": "14g", "fiber": "3g"}'::jsonb,'17'),
('18','Caprese Salad','Salads','Italian','Simple Italian salad with tomatoes, mozzarella, and basil.','8 min',2,'Easy',ARRAY['Vegetarian','Gluten-Free']::text[],ARRAY['Fresh mozzarella','Ripe tomatoes','Fresh basil','Extra virgin olive oil','Balsamic glaze','Sea salt']::text[],ARRAY['Slice tomatoes and mozzarella into 1/4 inch rounds.','Arrange alternating on a plate.','Tuck basil leaves between slices.','Drizzle with olive oil and balsamic glaze.','Sprinkle with sea salt.','Serve at room temperature.']::text[],'{"calories": 260, "protein": "14g", "carbs": "8g", "fat": "20g", "fiber": "2g"}'::jsonb,'18'),
('3','Chocolate Layer Cake','Desserts','American','Rich, moist chocolate cake with creamy chocolate ganache frosting.','60 min',12,'Medium',ARRAY['Vegetarian']::text[],ARRAY['2 cups all-purpose flour','2 cups sugar','3/4 cup cocoa powder','2 tsp baking soda','1 tsp baking powder','1 tsp salt','2 eggs','1 cup buttermilk','1 cup hot coffee','1/2 cup vegetable oil','2 tsp vanilla extract','For ganache: 2 cups heavy cream, 16 oz dark chocolate']::text[],ARRAY['Preheat oven to 350°F (175°C). Grease and flour two 9-inch round pans.','In a large bowl, mix flour, sugar, cocoa, baking soda, baking powder, and salt.','Add eggs, buttermilk, coffee, oil, and vanilla. Beat on medium for 2 minutes.','Pour batter evenly into prepared pans.','Bake for 30-35 minutes or until toothpick inserted comes out clean.','Cool in pans for 10 minutes, then remove to wire racks.','For ganache: Heat cream until just boiling, pour over chopped chocolate, let sit 5 minutes, then stir until smooth.','Let ganache cool to spreadable consistency.','Place one cake layer on serving plate, spread with ganache.','Top with second layer and cover entire cake with remaining ganache.','Refrigerate for 30 minutes before serving.']::text[],'{"calories": 520, "protein": "6g", "carbs": "62g", "fat": "28g", "fiber": "3g"}'::jsonb,'3'),
('19','Tiramisu','Desserts','Italian','Classic Italian coffee-flavored dessert with mascarpone cream.','30 min + chill',8,'Medium',ARRAY['Vegetarian']::text[],ARRAY['Ladyfinger cookies','Mascarpone cheese','Eggs','Sugar','Strong espresso','Cocoa powder','Coffee liqueur']::text[],ARRAY['Whip egg yolks with sugar until thick.','Fold in mascarpone cheese gently.','Beat egg whites to stiff peaks and fold in.','Dip ladyfingers quickly in espresso mixed with liqueur.','Layer soaked cookies in dish.','Spread half the mascarpone cream over cookies.','Repeat layers, ending with cream.','Dust with cocoa powder and refrigerate 4 hours.']::text[],'{"calories": 420, "protein": "8g", "carbs": "38g", "fat": "26g", "fiber": "1g"}'::jsonb,'19'),
('20','Apple Pie','Desserts','American','All-American apple pie with flaky crust and cinnamon filling.','90 min',8,'Medium',ARRAY['Vegetarian']::text[],ARRAY['Pie crust (2)','6 apples','Sugar','Cinnamon','Nutmeg','Butter','Lemon juice','Flour']::text[],ARRAY['Preheat oven to 425°F.','Peel and slice apples, toss with sugar, cinnamon, and lemon.','Line pie dish with bottom crust.','Fill with apple mixture and dot with butter.','Cover with top crust, seal edges, and cut vents.','Brush with egg wash and sprinkle with sugar.','Bake for 45-50 minutes until golden.','Cool before slicing.']::text[],'{"calories": 380, "protein": "4g", "carbs": "58g", "fat": "16g", "fiber": "4g"}'::jsonb,'20'),
('21','Crème Brûlée','Desserts','French','French custard dessert with caramelized sugar topping.','50 min + chill',6,'Hard',ARRAY['Vegetarian','Gluten-Free']::text[],ARRAY['Heavy cream','Egg yolks','Sugar','Vanilla bean','Extra sugar for topping']::text[],ARRAY['Heat cream with vanilla bean until just simmering.','Whisk egg yolks with sugar until pale.','Slowly add hot cream to yolks while whisking.','Strain mixture and pour into ramekins.','Bake in water bath at 325°F for 40 minutes.','Chill for at least 4 hours.','Sprinkle sugar on top and torch until caramelized.']::text[],'{"calories": 380, "protein": "5g", "carbs": "28g", "fat": "28g", "fiber": "0g"}'::jsonb,'21'),
('22','Cheesecake','Desserts','American','Creamy New York style cheesecake with graham cracker crust.','90 min + chill',12,'Medium',ARRAY['Vegetarian']::text[],ARRAY['Cream cheese','Sugar','Eggs','Sour cream','Vanilla','Graham crackers','Butter']::text[],ARRAY['Make crust by mixing crushed graham crackers with melted butter.','Press into springform pan and bake 10 minutes.','Beat cream cheese until smooth.','Add sugar, then eggs one at a time.','Mix in sour cream and vanilla.','Pour over crust and bake at 325°F for 60 minutes.','Cool completely then refrigerate overnight.']::text[],'{"calories": 480, "protein": "8g", "carbs": "42g", "fat": "32g", "fiber": "1g"}'::jsonb,'22'),
('4','Tropical Mango Smoothie','Drinks','International','Refreshing and creamy smoothie packed with tropical flavors.','5 min',2,'Easy',ARRAY['Vegetarian','Gluten-Free']::text[],ARRAY['2 cups frozen mango chunks','1 banana','1 cup coconut milk','1/2 cup orange juice','2 tbsp honey','1/2 cup Greek yogurt','Ice cubes (optional)','Fresh mint for garnish']::text[],ARRAY['Add frozen mango, banana, coconut milk, orange juice, and honey to blender.','Add Greek yogurt for extra creaminess.','Blend on high until completely smooth, about 1-2 minutes.','Add ice cubes if you want it thicker.','Taste and adjust sweetness with more honey if needed.','Pour into glasses and garnish with fresh mint.','Serve immediately while cold.']::text[],'{"calories": 280, "protein": "8g", "carbs": "52g", "fat": "6g", "fiber": "4g"}'::jsonb,'4'),
('23','Green Detox Smoothie','Drinks','International','Healthy green smoothie packed with nutrients.','5 min',2,'Easy',ARRAY['Vegan','Gluten-Free']::text[],ARRAY['Spinach','Kale','Banana','Apple','Ginger','Lemon juice','Water or coconut water']::text[],ARRAY['Add all greens to blender first.','Add chopped fruits and ginger.','Pour in liquid.','Blend until completely smooth.','Add more liquid if too thick.','Serve immediately over ice.']::text[],'{"calories": 140, "protein": "3g", "carbs": "32g", "fat": "1g", "fiber": "6g"}'::jsonb,'23'),
('24','Iced Coffee','Drinks','American','Refreshing cold coffee with milk and ice.','5 min',1,'Easy',ARRAY['Vegetarian','Gluten-Free']::text[],ARRAY['Strong brewed coffee, chilled','Ice cubes','Milk or cream','Sugar or sweetener','Vanilla extract (optional)']::text[],ARRAY['Fill glass with ice cubes.','Pour chilled coffee over ice.','Add milk to desired creaminess.','Sweeten to taste.','Stir well and enjoy.']::text[],'{"calories": 80, "protein": "2g", "carbs": "12g", "fat": "2g", "fiber": "0g"}'::jsonb,'24'),
('25','Fresh Lemonade','Drinks','American','Classic homemade lemonade with fresh squeezed lemons.','10 min',6,'Easy',ARRAY['Vegan','Gluten-Free']::text[],ARRAY['8 lemons','1 cup sugar','6 cups cold water','Ice','Mint for garnish']::text[],ARRAY['Juice all lemons to get about 1.5 cups of juice.','Make simple syrup by heating sugar with 1 cup water.','Mix lemon juice, simple syrup, and remaining water.','Stir well and taste, adjust sweetness.','Chill in refrigerator.','Serve over ice with mint garnish.']::text[],'{"calories": 110, "protein": "0g", "carbs": "28g", "fat": "0g", "fiber": "0g"}'::jsonb,'25'),
('26','Hot Chocolate','Drinks','International','Rich and creamy hot chocolate with marshmallows.','8 min',2,'Easy',ARRAY['Vegetarian','Gluten-Free']::text[],ARRAY['Milk','Dark chocolate','Cocoa powder','Sugar','Vanilla','Marshmallows','Whipped cream']::text[],ARRAY['Heat milk in saucepan over medium heat.','Whisk in cocoa powder and sugar.','Add chopped chocolate and stir until melted.','Add vanilla extract.','Pour into mugs.','Top with marshmallows and whipped cream.']::text[],'{"calories": 320, "protein": "10g", "carbs": "42g", "fat": "14g", "fiber": "3g"}'::jsonb,'26'),
('5','Hearty Vegetable Soup','Soups','International','Comforting vegetable soup loaded with nutritious ingredients.','45 min',6,'Easy',ARRAY['Vegan','Gluten-Free']::text[],ARRAY['2 tbsp olive oil','1 onion, diced','3 carrots, sliced','3 celery stalks, sliced','3 cloves garlic, minced','1 can diced tomatoes','6 cups vegetable broth','2 cups green beans, chopped','2 cups potatoes, diced','1 cup corn kernels','2 bay leaves','1 tsp thyme','Salt and pepper to taste','Fresh parsley for garnish']::text[],ARRAY['Heat olive oil in a large pot over medium heat.','Add onion, carrots, and celery. Cook for 5 minutes until softened.','Add garlic and cook for 1 minute.','Pour in diced tomatoes and vegetable broth.','Add potatoes, green beans, corn, bay leaves, and thyme.','Bring to a boil, then reduce heat and simmer for 30 minutes.','Season with salt and pepper to taste.','Remove bay leaves before serving.','Garnish with fresh parsley.','Serve hot with crusty bread.']::text[],'{"calories": 160, "protein": "4g", "carbs": "28g", "fat": "4g", "fiber": "6g"}'::jsonb,'5'),
('27','Chicken Noodle Soup','Soups','American','Classic comfort soup with tender chicken and noodles.','40 min',6,'Easy',ARRAY[]::text[],ARRAY['Chicken breast','Egg noodles','Carrots','Celery','Onion','Chicken broth','Bay leaf','Thyme']::text[],ARRAY['Bring chicken broth to boil with chicken breast.','Simmer for 20 minutes until chicken is cooked.','Remove chicken, shred, and set aside.','Add chopped vegetables to broth.','Simmer until vegetables are tender.','Add noodles and cook until done.','Return shredded chicken to pot.','Season and serve hot.']::text[],'{"calories": 220, "protein": "18g", "carbs": "24g", "fat": "5g", "fiber": "2g"}'::jsonb,'27'),
('28','French Onion Soup','Soups','French','Rich caramelized onion soup with cheese-topped croutons.','60 min',4,'Medium',ARRAY['Vegetarian']::text[],ARRAY['5 large onions','Butter','Beef broth','White wine','Thyme','French bread','Gruyere cheese']::text[],ARRAY['Thinly slice onions.','Caramelize in butter for 30-40 minutes on low heat.','Add wine and simmer until reduced.','Add broth and thyme, simmer 20 minutes.','Toast bread slices.','Ladle soup into oven-safe bowls.','Top with bread and cheese, broil until melted.']::text[],'{"calories": 340, "protein": "14g", "carbs": "32g", "fat": "18g", "fiber": "4g"}'::jsonb,'28'),
('29','Tom Yum Soup','Soups','Thai','Spicy and sour Thai soup with shrimp and lemongrass.','25 min',4,'Medium',ARRAY['Gluten-Free']::text[],ARRAY['Shrimp','Lemongrass','Galangal','Lime leaves','Thai chilies','Fish sauce','Lime juice','Mushrooms','Tomatoes']::text[],ARRAY['Bring broth to boil with lemongrass, galangal, and lime leaves.','Add mushrooms and simmer 5 minutes.','Add shrimp and cook until pink.','Add tomatoes and chilies.','Season with fish sauce and lime juice.','Garnish with cilantro and serve hot.']::text[],'{"calories": 180, "protein": "22g", "carbs": "12g", "fat": "4g", "fiber": "2g"}'::jsonb,'29'),
('30','Minestrone','Soups','Italian','Italian vegetable soup with beans and pasta.','50 min',8,'Easy',ARRAY['Vegetarian']::text[],ARRAY['Onion, carrots, celery','Tomatoes','Kidney beans','Green beans','Zucchini','Small pasta','Vegetable broth','Italian herbs','Parmesan']::text[],ARRAY['Sauté onion, carrots, and celery in olive oil.','Add garlic and cook 1 minute.','Add broth, tomatoes, and beans.','Simmer 20 minutes.','Add zucchini, green beans, and pasta.','Cook until pasta is tender.','Season with herbs, salt, and pepper.','Serve with grated parmesan.']::text[],'{"calories": 190, "protein": "8g", "carbs": "32g", "fat": "3g", "fiber": "7g"}'::jsonb,'30'),
('6','Avocado Toast','Breakfast','American','Trendy and nutritious breakfast with perfectly seasoned avocado.','10 min',2,'Easy',ARRAY['Vegetarian']::text[],ARRAY['4 slices whole grain bread','2 ripe avocados','2 eggs','1 tbsp lemon juice','Red pepper flakes','Salt and pepper','Cherry tomatoes, halved','Microgreens or arugula','Everything bagel seasoning']::text[],ARRAY['Toast bread slices until golden and crispy.','Mash avocados in a bowl with lemon juice, salt, and pepper.','Spread mashed avocado evenly on toast.','Fry or poach eggs to your preference.','Top each toast with a cooked egg.','Add cherry tomatoes and microgreens.','Sprinkle with everything bagel seasoning and red pepper flakes.','Serve immediately while toast is still warm.']::text[],'{"calories": 380, "protein": "14g", "carbs": "35g", "fat": "22g", "fiber": "12g"}'::jsonb,'6'),
('31','Pancakes','Breakfast','American','Fluffy American-style pancakes with maple syrup.','20 min',4,'Easy',ARRAY['Vegetarian']::text[],ARRAY['Flour','Milk','Eggs','Baking powder','Sugar','Butter','Vanilla','Maple syrup','Berries']::text[],ARRAY['Mix dry ingredients in a bowl.','Whisk together wet ingredients.','Combine wet and dry, don''t overmix.','Heat griddle and melt butter.','Pour 1/4 cup batter per pancake.','Flip when bubbles form.','Serve with syrup and berries.']::text[],'{"calories": 340, "protein": "10g", "carbs": "52g", "fat": "10g", "fiber": "2g"}'::jsonb,'31'),
('32','Eggs Benedict','Breakfast','American','Classic brunch dish with poached eggs and hollandaise sauce.','25 min',2,'Hard',ARRAY[]::text[],ARRAY['English muffins','Eggs','Canadian bacon','Butter','Lemon juice','Cayenne','White vinegar']::text[],ARRAY['Make hollandaise: whisk egg yolks with lemon over double boiler.','Slowly add melted butter while whisking.','Season with cayenne and salt.','Poach eggs in simmering water with vinegar.','Toast English muffins.','Warm Canadian bacon in pan.','Assemble: muffin, bacon, egg, hollandaise.']::text[],'{"calories": 520, "protein": "24g", "carbs": "28g", "fat": "36g", "fiber": "2g"}'::jsonb,'32'),
('33','Açaí Bowl','Breakfast','Brazilian','Nutritious Brazilian breakfast bowl with frozen açaí and toppings.','10 min',2,'Easy',ARRAY['Vegan','Gluten-Free']::text[],ARRAY['Acai packets','Banana','Berries','Granola','Honey','Coconut flakes','Almond butter']::text[],ARRAY['Blend frozen açaí with banana and a splash of juice.','Pour into bowl.','Top with sliced banana and berries.','Add granola and coconut flakes.','Drizzle with honey and almond butter.','Serve immediately while frozen.']::text[],'{"calories": 380, "protein": "8g", "carbs": "62g", "fat": "12g", "fiber": "10g"}'::jsonb,'33'),
('34','French Toast','Breakfast','American','Classic breakfast with cinnamon-vanilla battered bread.','15 min',4,'Easy',ARRAY['Vegetarian']::text[],ARRAY['Brioche or thick bread','Eggs','Milk','Cinnamon','Vanilla','Butter','Powdered sugar','Maple syrup']::text[],ARRAY['Whisk eggs, milk, cinnamon, and vanilla.','Dip bread slices in egg mixture.','Cook in buttered pan until golden on both sides.','Dust with powdered sugar.','Serve with maple syrup and berries.']::text[],'{"calories": 360, "protein": "12g", "carbs": "48g", "fat": "14g", "fiber": "2g"}'::jsonb,'34'),
('35','Classic Omelette','Breakfast','French','A perfectly folded French omelette with creamy cheese filling and fresh herbs.','10 min',1,'Easy',ARRAY['Vegetarian','Gluten-Free','Keto']::text[],ARRAY['3 large eggs','1 tbsp butter','2 tbsp grated cheese (gruyère or cheddar)','1 tbsp fresh chives, chopped','Salt and pepper to taste','1 tbsp milk or cream (optional)']::text[],ARRAY['Crack eggs into a bowl and whisk until well combined.','Add milk or cream if using, season with salt and pepper.','Heat a non-stick pan over medium heat and add butter.','When butter foams, pour in the egg mixture.','Let eggs set slightly, then gently push edges toward center.','When omelette is still slightly wet on top, add cheese to one half.','Fold the omelette in half and slide onto a plate.','Garnish with fresh chives and serve immediately.']::text[],'{"calories": 320, "protein": "21g", "carbs": "2g", "fat": "25g", "fiber": "0g"}'::jsonb,'35'),
('100','Risotto alla Milanese','Meals','Italian','Creamy saffron risotto from Milan, rich and aromatic.','35 min',4,'Medium',ARRAY['Vegetarian','Gluten-Free']::text[],ARRAY['Arborio rice','Saffron threads','White wine','Parmesan','Butter','Onion','Chicken broth']::text[],ARRAY['Toast saffron threads and soak in warm broth.','Sauté finely diced onion in butter until soft.','Add rice and toast for 2 minutes.','Add wine and stir until absorbed.','Add broth one ladle at a time, stirring constantly.','Cook for 20 minutes until creamy.','Stir in butter and parmesan before serving.']::text[],'{"calories": 420, "protein": "12g", "carbs": "58g", "fat": "15g", "fiber": "2g"}'::jsonb,'100'),
('101','Osso Buco','Meals','Italian','Braised veal shanks in white wine with vegetables.','150 min',6,'Hard',ARRAY['Gluten-Free']::text[],ARRAY['Veal shanks','White wine','Tomatoes','Carrots','Celery','Onion','Garlic','Gremolata']::text[],ARRAY['Tie veal shanks with kitchen twine.','Brown shanks in olive oil on all sides.','Sauté vegetables until soft.','Add wine and reduce by half.','Add tomatoes and broth, bring to simmer.','Braise in oven at 325°F for 2 hours.','Top with gremolata before serving.']::text[],'{"calories": 520, "protein": "42g", "carbs": "18g", "fat": "28g", "fiber": "3g"}'::jsonb,'101'),
('102','Chicken Mole Poblano','Meals','Mexican','Complex sauce with chocolate and chilies over chicken.','120 min',8,'Hard',ARRAY['Gluten-Free']::text[],ARRAY['Chicken pieces','Dried chilies','Dark chocolate','Tomatoes','Almonds','Sesame seeds','Spices']::text[],ARRAY['Toast and rehydrate dried chilies.','Blend chilies with tomatoes, nuts, and spices.','Fry the mole paste in oil.','Add chocolate and chicken broth.','Simmer for 45 minutes.','Add cooked chicken pieces.','Simmer 30 more minutes, serve with rice.']::text[],'{"calories": 480, "protein": "38g", "carbs": "24g", "fat": "26g", "fiber": "5g"}'::jsonb,'102'),
('103','Chiles Rellenos','Meals','Mexican','Roasted poblano peppers stuffed with cheese.','45 min',6,'Medium',ARRAY['Vegetarian','Gluten-Free']::text[],ARRAY['Poblano peppers','Queso fresco','Eggs','Flour','Tomato sauce','Onion','Garlic']::text[],ARRAY['Char peppers over flame until blackened.','Peel skin and make slit to remove seeds.','Stuff with cheese.','Coat in flour, then egg batter.','Fry until golden.','Serve with warm tomato sauce.']::text[],'{"calories": 320, "protein": "16g", "carbs": "22g", "fat": "18g", "fiber": "4g"}'::jsonb,'103'),
('104','Green Curry','Meals','Thai','Aromatic Thai curry with coconut milk and vegetables.','35 min',4,'Medium',ARRAY['Gluten-Free']::text[],ARRAY['Green curry paste','Coconut milk','Chicken or tofu','Thai basil','Bamboo shoots','Thai eggplant','Fish sauce']::text[],ARRAY['Fry curry paste in coconut cream until fragrant.','Add remaining coconut milk and bring to simmer.','Add protein and cook through.','Add vegetables and simmer until tender.','Season with fish sauce and sugar.','Add Thai basil and serve with rice.']::text[],'{"calories": 420, "protein": "28g", "carbs": "18g", "fat": "28g", "fiber": "3g"}'::jsonb,'104'),
('105','Som Tam (Papaya Salad)','Salads','Thai','Spicy and tangy green papaya salad.','15 min',4,'Easy',ARRAY['Vegan','Gluten-Free']::text[],ARRAY['Green papaya','Cherry tomatoes','Long beans','Peanuts','Thai chilies','Lime','Palm sugar','Tamarind']::text[],ARRAY['Shred green papaya into thin strips.','Pound chilies and garlic in mortar.','Add palm sugar, lime juice, and tamarind.','Add papaya, tomatoes, and beans.','Pound lightly to bruise.','Top with peanuts and serve.']::text[],'{"calories": 140, "protein": "4g", "carbs": "22g", "fat": "5g", "fiber": "4g"}'::jsonb,'105'),
('106','Butter Chicken','Meals','Indian','Creamy tomato-based curry with tender chicken.','50 min',6,'Medium',ARRAY['Gluten-Free']::text[],ARRAY['Chicken','Tomatoes','Butter','Cream','Garam masala','Ginger','Garlic','Fenugreek leaves']::text[],ARRAY['Marinate chicken in yogurt and spices.','Grill or bake chicken until cooked.','Make sauce with butter, tomatoes, and spices.','Blend sauce until smooth.','Add cream and cooked chicken.','Simmer for 15 minutes.','Garnish with cream and fenugreek.']::text[],'{"calories": 480, "protein": "36g", "carbs": "12g", "fat": "32g", "fiber": "2g"}'::jsonb,'106'),
('107','Palak Paneer','Meals','Indian','Spinach curry with Indian cottage cheese.','40 min',4,'Medium',ARRAY['Vegetarian','Gluten-Free']::text[],ARRAY['Spinach','Paneer','Onion','Tomatoes','Cream','Ginger','Garlic','Garam masala']::text[],ARRAY['Blanch spinach and blend to smooth paste.','Fry paneer cubes until golden, set aside.','Sauté onion, ginger, and garlic.','Add tomatoes and cook until soft.','Add spinach puree and spices.','Simmer for 10 minutes.','Add paneer and cream, heat through.']::text[],'{"calories": 340, "protein": "18g", "carbs": "15g", "fat": "24g", "fiber": "5g"}'::jsonb,'107'),
('108','Chana Masala','Meals','Indian','Spiced chickpea curry, hearty and flavorful.','35 min',6,'Easy',ARRAY['Vegan','Gluten-Free']::text[],ARRAY['Chickpeas','Tomatoes','Onion','Ginger','Garlic','Garam masala','Cumin','Coriander']::text[],ARRAY['Sauté onion until golden.','Add ginger, garlic, and spices.','Add tomatoes and cook until soft.','Add chickpeas and water.','Simmer for 20 minutes.','Mash some chickpeas for thickness.','Garnish with cilantro.']::text[],'{"calories": 280, "protein": "12g", "carbs": "42g", "fat": "6g", "fiber": "10g"}'::jsonb,'108'),
('109','Ramen','Soups','Japanese','Rich broth with noodles, pork, and toppings.','120 min',4,'Hard',ARRAY[]::text[],ARRAY['Pork belly','Ramen noodles','Pork bones','Soy sauce','Mirin','Soft boiled eggs','Green onions','Nori']::text[],ARRAY['Simmer pork bones for 8 hours for broth.','Braise pork belly in soy and mirin.','Cook ramen noodles.','Assemble: broth, noodles, sliced pork.','Top with egg, green onions, and nori.']::text[],'{"calories": 580, "protein": "32g", "carbs": "62g", "fat": "22g", "fiber": "3g"}'::jsonb,'109'),
('110','Tempura','Meals','Japanese','Light and crispy battered vegetables and shrimp.','30 min',4,'Medium',ARRAY[]::text[],ARRAY['Shrimp','Vegetables','Tempura batter mix','Ice water','Oil for frying','Tentsuyu dipping sauce']::text[],ARRAY['Prepare vegetables and shrimp.','Make batter with ice cold water.','Heat oil to 350°F.','Dip ingredients in batter.','Fry until light golden.','Drain on paper towels.','Serve immediately with dipping sauce.']::text[],'{"calories": 380, "protein": "18g", "carbs": "38g", "fat": "16g", "fiber": "3g"}'::jsonb,'110'),
('111','Miso Soup','Soups','Japanese','Traditional Japanese soup with tofu and seaweed.','15 min',4,'Easy',ARRAY['Vegan','Gluten-Free']::text[],ARRAY['Miso paste','Dashi','Tofu','Wakame seaweed','Green onions']::text[],ARRAY['Heat dashi broth until simmering.','Add cubed tofu and wakame.','Remove from heat.','Dissolve miso paste in small amount of broth.','Stir miso into soup.','Garnish with green onions.','Serve immediately, do not boil.']::text[],'{"calories": 90, "protein": "6g", "carbs": "8g", "fat": "3g", "fiber": "2g"}'::jsonb,'111'),
('112','Coq au Vin','Meals','French','Chicken braised in red wine with mushrooms and bacon.','120 min',6,'Hard',ARRAY['Gluten-Free']::text[],ARRAY['Chicken','Red wine','Bacon','Pearl onions','Mushrooms','Thyme','Bay leaf','Chicken stock']::text[],ARRAY['Brown bacon and remove.','Brown chicken pieces in bacon fat.','Sauté onions and mushrooms.','Deglaze pan with wine.','Add stock, herbs, and chicken back.','Braise for 90 minutes until tender.','Reduce sauce and serve.']::text[],'{"calories": 520, "protein": "42g", "carbs": "12g", "fat": "28g", "fiber": "2g"}'::jsonb,'112'),
('113','Ratatouille','Meals','French','Provençal vegetable stew with herbs.','60 min',6,'Medium',ARRAY['Vegan','Gluten-Free']::text[],ARRAY['Eggplant','Zucchini','Bell peppers','Tomatoes','Onion','Garlic','Herbes de Provence','Olive oil']::text[],ARRAY['Slice vegetables thinly.','Sauté onion and garlic in olive oil.','Add tomatoes and cook into sauce.','Arrange vegetable slices in dish.','Pour sauce over vegetables.','Drizzle with olive oil and herbs.','Bake at 375°F for 45 minutes.']::text[],'{"calories": 180, "protein": "4g", "carbs": "24g", "fat": "8g", "fiber": "8g"}'::jsonb,'113'),
('114','Moussaka','Meals','Greek','Layered eggplant casserole with meat sauce and béchamel.','90 min',8,'Hard',ARRAY[]::text[],ARRAY['Eggplant','Ground lamb','Tomatoes','Onion','Béchamel sauce','Parmesan','Cinnamon']::text[],ARRAY['Slice and salt eggplant, let drain.','Make meat sauce with lamb, tomatoes, and spices.','Fry eggplant slices until golden.','Make béchamel sauce.','Layer: eggplant, meat sauce, repeat.','Top with béchamel and cheese.','Bake at 350°F for 45 minutes.']::text[],'{"calories": 480, "protein": "28g", "carbs": "32g", "fat": "26g", "fiber": "6g"}'::jsonb,'114'),
('115','Spanakopita','Meals','Greek','Spinach and feta pie wrapped in phyllo.','60 min',8,'Medium',ARRAY['Vegetarian']::text[],ARRAY['Phyllo dough','Spinach','Feta cheese','Eggs','Dill','Onion','Butter']::text[],ARRAY['Sauté onion until soft.','Add spinach and cook until wilted.','Mix with feta, eggs, and dill.','Layer phyllo sheets, brushing with butter.','Add spinach filling.','Top with more phyllo layers.','Bake at 350°F for 45 minutes until golden.']::text[],'{"calories": 340, "protein": "14g", "carbs": "28g", "fat": "20g", "fiber": "3g"}'::jsonb,'115'),
('116','Kung Pao Chicken','Meals','Chinese','Spicy stir-fry with peanuts and dried chilies.','25 min',4,'Medium',ARRAY[]::text[],ARRAY['Chicken breast','Peanuts','Dried chilies','Sichuan peppercorns','Soy sauce','Rice vinegar','Sugar','Cornstarch']::text[],ARRAY['Marinate chicken in soy sauce and cornstarch.','Stir-fry chicken until golden, remove.','Fry chilies and peppercorns in oil.','Add sauce mixture and bring to boil.','Return chicken to wok.','Add peanuts and toss.','Serve over rice.']::text[],'{"calories": 420, "protein": "32g", "carbs": "18g", "fat": "24g", "fiber": "3g"}'::jsonb,'116'),
('117','Mapo Tofu','Meals','Chinese','Spicy Sichuan tofu dish with ground pork.','30 min',4,'Easy',ARRAY['Gluten-Free']::text[],ARRAY['Soft tofu','Ground pork','Doubanjiang','Sichuan peppercorns','Garlic','Ginger','Green onions']::text[],ARRAY['Cut tofu into cubes.','Brown ground pork in wok.','Add garlic, ginger, and doubanjiang.','Add broth and bring to simmer.','Gently add tofu.','Simmer for 10 minutes.','Garnish with green onions and peppercorns.']::text[],'{"calories": 320, "protein": "22g", "carbs": "8g", "fat": "22g", "fiber": "2g"}'::jsonb,'117'),
('118','Falafel','Meals','Middle Eastern','Crispy chickpea fritters with herbs and spices.','40 min',6,'Medium',ARRAY['Vegan','Gluten-Free']::text[],ARRAY['Dried chickpeas','Parsley','Cilantro','Onion','Garlic','Cumin','Coriander','Baking powder']::text[],ARRAY['Soak chickpeas overnight.','Blend chickpeas with herbs and spices.','Form into small balls or patties.','Let rest in fridge for 1 hour.','Deep fry at 350°F until golden.','Drain on paper towels.','Serve in pita with tahini sauce.']::text[],'{"calories": 280, "protein": "12g", "carbs": "38g", "fat": "8g", "fiber": "10g"}'::jsonb,'118'),
('119','Hummus','Meals','Middle Eastern','Creamy chickpea dip with tahini and lemon.','15 min',8,'Easy',ARRAY['Vegan','Gluten-Free']::text[],ARRAY['Chickpeas','Tahini','Lemon juice','Garlic','Cumin','Olive oil','Paprika']::text[],ARRAY['Blend chickpeas until smooth.','Add tahini, lemon juice, and garlic.','Blend until creamy, adding water as needed.','Season with cumin and salt.','Transfer to serving bowl.','Drizzle with olive oil.','Sprinkle with paprika.']::text[],'{"calories": 180, "protein": "6g", "carbs": "18g", "fat": "10g", "fiber": "5g"}'::jsonb,'119'),
('120','Tabbouleh','Salads','Middle Eastern','Fresh parsley salad with bulgur and tomatoes.','20 min',6,'Easy',ARRAY['Vegan']::text[],ARRAY['Bulgur wheat','Parsley','Mint','Tomatoes','Cucumber','Lemon juice','Olive oil']::text[],ARRAY['Soak bulgur in water for 15 minutes.','Finely chop parsley and mint.','Dice tomatoes and cucumber.','Drain bulgur and mix with herbs and vegetables.','Dress with lemon juice and olive oil.','Season with salt and pepper.','Chill before serving.']::text[],'{"calories": 140, "protein": "4g", "carbs": "22g", "fat": "5g", "fiber": "5g"}'::jsonb,'120'),
('121','Bibimbap','Meals','Korean','Mixed rice bowl with vegetables, egg, and gochujang.','45 min',4,'Medium',ARRAY['Gluten-Free']::text[],ARRAY['Rice','Beef','Spinach','Bean sprouts','Carrots','Mushrooms','Egg','Gochujang','Sesame oil']::text[],ARRAY['Cook rice and keep warm.','Marinate and cook beef.','Blanch spinach and bean sprouts separately.','Sauté carrots and mushrooms.','Fry eggs sunny-side up.','Arrange vegetables and beef over rice in bowl.','Top with egg and gochujang.']::text[],'{"calories": 520, "protein": "28g", "carbs": "68g", "fat": "14g", "fiber": "6g"}'::jsonb,'121'),
('122','Kimchi','Meals','Korean','Fermented spicy cabbage, Korean staple.','30 min + ferment',16,'Medium',ARRAY['Vegan','Gluten-Free']::text[],ARRAY['Napa cabbage','Korean chili flakes','Fish sauce (or soy)','Garlic','Ginger','Sugar','Green onions']::text[],ARRAY['Salt cabbage and let sit 2 hours.','Rinse and drain cabbage.','Make paste with chili flakes, garlic, ginger, and fish sauce.','Coat cabbage with paste.','Pack into jars.','Ferment at room temperature for 2-5 days.','Store in refrigerator.']::text[],'{"calories": 30, "protein": "2g", "carbs": "6g", "fat": "0g", "fiber": "2g"}'::jsonb,'122'),
('123','Pho','Soups','Vietnamese','Aromatic beef noodle soup with herbs.','180 min',6,'Hard',ARRAY['Gluten-Free']::text[],ARRAY['Beef bones','Rice noodles','Beef slices','Star anise','Cinnamon','Fish sauce','Bean sprouts','Thai basil','Lime']::text[],ARRAY['Char onion and ginger.','Simmer bones with spices for 6+ hours.','Strain broth and season with fish sauce.','Cook rice noodles.','Assemble: noodles, raw beef, hot broth.','Top with herbs, bean sprouts, lime.','Serve with hoisin and sriracha.']::text[],'{"calories": 420, "protein": "32g", "carbs": "52g", "fat": "8g", "fiber": "2g"}'::jsonb,'123'),
('124','Banh Mi','Meals','Vietnamese','Vietnamese sandwich with pickled vegetables and pâté.','30 min',4,'Easy',ARRAY[]::text[],ARRAY['Baguette','Pork','Pâté','Pickled carrots and daikon','Cucumber','Cilantro','Jalapeños','Mayo']::text[],ARRAY['Marinate and grill pork.','Make quick pickled vegetables.','Slice baguette and toast lightly.','Spread pâté and mayo on bread.','Layer with pork, pickles, cucumber.','Add cilantro and jalapeños.','Serve immediately.']::text[],'{"calories": 480, "protein": "26g", "carbs": "52g", "fat": "18g", "fiber": "4g"}'::jsonb,'124'),
('125','Paella','Meals','Spanish','Saffron rice with seafood and chicken.','60 min',6,'Hard',ARRAY['Gluten-Free']::text[],ARRAY['Bomba rice','Chicken','Shrimp','Mussels','Saffron','Bell peppers','Peas','Paprika','Chicken stock']::text[],ARRAY['Brown chicken in paella pan.','Sauté peppers and tomatoes.','Add rice and toast.','Add saffron-infused stock.','Arrange chicken and seafood on top.','Cook without stirring for 20 minutes.','Let rest 5 minutes before serving.']::text[],'{"calories": 520, "protein": "38g", "carbs": "56g", "fat": "14g", "fiber": "3g"}'::jsonb,'125'),
('126','Gazpacho','Soups','Spanish','Cold tomato soup, refreshing and healthy.','15 min + chill',6,'Easy',ARRAY['Vegan','Gluten-Free']::text[],ARRAY['Tomatoes','Cucumber','Bell pepper','Onion','Garlic','Olive oil','Sherry vinegar','Bread (optional)']::text[],ARRAY['Roughly chop all vegetables.','Blend until smooth.','Add olive oil and vinegar.','Season with salt and pepper.','Chill for at least 2 hours.','Serve cold with garnishes.','Drizzle with olive oil.']::text[],'{"calories": 120, "protein": "2g", "carbs": "14g", "fat": "7g", "fiber": "3g"}'::jsonb,'126'),
('127','Tagine','Meals','Moroccan','Slow-cooked stew with lamb, dried fruits, and spices.','120 min',6,'Medium',ARRAY['Gluten-Free']::text[],ARRAY['Lamb','Onions','Dried apricots','Almonds','Honey','Cinnamon','Cumin','Saffron','Chickpeas']::text[],ARRAY['Brown lamb in tagine or heavy pot.','Add onions and spices.','Add broth and chickpeas.','Simmer for 90 minutes.','Add dried fruits and almonds.','Cook 20 more minutes.','Drizzle with honey before serving.']::text[],'{"calories": 540, "protein": "36g", "carbs": "42g", "fat": "24g", "fiber": "8g"}'::jsonb,'127');
